evals.prompt:
Use this fictional streaming backend as code evidence. Locate the actual guards in the snippet before modeling billing, playback, and youth-profile rules. The fictional requirements also mention grace-period expiry, refunds, and tier changes. Add unsupported items to the open or deferred list. Define vocabulary and fact types before the rules.

const PREVIEW_FORMATS = new Set(["trailer", "sample"]);
function canViewVideo(account, format) {
  return PREVIEW_FORMATS.has(format) || ["evaluation", "paid", "retry"].includes(account?.status);
}
function allowsProfileRating(profile, rating) {
  return profile?.youthOnly ? ["G", "PG"].includes(rating) : true;
}
function completeSandboxCheckout(environment) {
  return environment === "sandbox" ? 204 : 404;
}
